using CleanHome.Payment.Api.Interfaces;
using CleanHome.Payment.Api.Models;
using CleanHome.Payment.Api.DTOs;
using CleanHome.ServiceDefaults;
namespace CleanHome.Payment.Api.Services;
public sealed class PaymentService(IPaymentRepository repository,OrderPaymentClient orders,VnPayGateway gateway){
 public async Task<PaymentOrder> Enroll(long id,CancellationToken ct)=>await repository.Enroll(await orders.Fact(id,ct),ct);
 public async Task<object> Status(long id,long actor,string role,CancellationToken ct){var fact=await orders.Fact(id,ct);var assignments=role=="staff"?await orders.Assignments(id,ct):[];if(role!="admin"&&!(role=="customer"&&fact.CustomerId==actor)&&!assignments.Any(a=>a.UserId==actor))throw new ApiException(404,"Không có thanh toán thuộc quyền của bạn.");var o=await repository.Enroll(fact,ct);if(fact.WorkStatus=="cancelled"){await repository.Cancel(id,ct);o=await repository.Read(id,ct);}var work=fact.WorkStatus=="pending_payment"?"PENDING_PAYMENT":fact.WorkStatus=="pending"?"SEARCHING_EMPLOYEE":fact.WorkStatus=="confirmed"?"ASSIGNED":fact.WorkStatus.ToUpperInvariant();return new{o.BookingId,o.Code,o.Amount,o.Method,o.Status,o.Revision,o.CollectorEmployeeId,o.CollectedAt,o.PaidAt,orderStatus=work,canCollect=role=="staff"&&o.CollectorUserId==actor&&o.Method=="CASH"&&o.Status=="UNPAID"&&fact.WorkStatus=="completed",canConfirm=role=="customer"&&o.Status=="CASH_AWAITING_CONFIRMATION",canPay=role=="customer"&&o.Method=="VNPAY"&&o.Status is "PENDING" or "FAILED"&&fact.WorkStatus=="pending_payment"&&!fact.CancellationPending};}
 public async Task<object> Create(CheckoutRequest request,long actor,string ip,CancellationToken ct){var fact=await orders.Fact(request.OrderId,ct);if(fact.CustomerId!=actor)throw new ApiException(404,"Không có đơn của bạn.");var attempt=await repository.Create(fact,request.IdempotencyKey,ip,gateway.Create,ct);return new{attempt.Reference,paymentUrl=attempt.Url,attempt.ExpiresAt,attempt.Status};}
 public async Task Collect(long id,long actor,CancellationToken ct){var fact=await orders.Fact(id,ct);if(fact.Method!="CASH"||fact.WorkStatus!="completed")throw new ApiException(409,"Chỉ thu tiền mặt khi toàn bộ dịch vụ hoàn thành.");var assignments=await orders.Assignments(id,ct);if(!assignments.Any(a=>a.UserId==actor&&a.Status=="done"))throw new ApiException(403,"Không có quyền thu tiền cho đơn.");await repository.Enroll(fact,ct);await repository.Mutate(id,actor,"collect","Nhân viên xác nhận nhận đủ số tiền trên đơn",null,null,ct);}
 public async Task Customer(CashRequest request,long actor,CancellationToken ct){var fact=await orders.Fact(request.OrderId,ct);if(fact.CustomerId!=actor)throw new ApiException(404,"Không có đơn của bạn.");if(fact.WorkStatus!="completed")throw new ApiException(409,"Đơn chưa hoàn thành.");await repository.Mutate(request.OrderId,actor,request.Paid?"customer_paid":"customer_disputed",request.Paid?"Khách xác nhận đã thanh toán":"Khách báo chưa thanh toán",null,null,ct);}
 public async Task Admin(long id,string action,AdminPaymentRequest request,long actor,CancellationToken ct){await Enroll(id,ct);if(action=="collector"){var assignments=await orders.Assignments(id,ct);var target=assignments.SingleOrDefault(a=>a.EmployeeId==request.EmployeeId&&a.Status is "accepted" or "in_progress" or "done")??throw new ApiException(409,"Chọn nhân viên đã nhận thành công trong đơn.");await repository.Mutate(id,actor,action,request.Evidence,target.EmployeeId,target.UserId,ct);}else if(action=="resolve"){var fact=await orders.Fact(id,ct);if(fact.WorkStatus!="completed")throw new ApiException(409,"Đơn chưa hoàn thành.");await repository.Mutate(id,actor,request.Paid?"resolve_paid":"resolve_unpaid",request.Evidence,null,null,ct);}else if(action=="refund-request"){await repository.Mutate(id,actor,"refund_request",request.Evidence,null,null,ct);}else throw new ApiException(400,"Thao tác không hợp lệ.");}
 public async Task Sync(long id,CancellationToken ct){var fact=await orders.Fact(id,ct);var row=await repository.Read(id,ct);if(fact.WorkStatus=="cancelled")await repository.Cancel(id,ct);else if(row.Method=="CASH"&&row.Status=="UNPAID"&&row.CollectedAt is null){var assignments=await orders.Assignments(id,ct);var candidates=assignments.Where(a=>a.Status is "accepted" or "in_progress" or "done").OrderBy(a=>a.Id).ToArray();if(candidates.Length>0&&(row.CollectorEmployeeId is null||!candidates.Any(a=>a.EmployeeId==row.CollectorEmployeeId))){try{await repository.Mutate(id,0,"collector","Hệ thống chỉ định một người thu theo thứ tự nhận việc",candidates[0].EmployeeId,candidates[0].UserId,ct);}catch(ApiException e)when(e.Status==409){}}}row=await repository.Read(id,ct);await orders.Mirror(row,ct);await repository.SyncMark(id,row.Revision,ct);}
 public async Task Refund(long id,long caseId,long actor,string evidence,CancellationToken ct){await repository.Refund(id,caseId,actor,evidence,ct);}
 public async Task Reconcile(string reference,CancellationToken ct){var attempt=await repository.Attempt(reference,ct)??throw new ApiException(404,"Không có giao dịch.");if(!await repository.ReserveQuery(reference,ct))throw new ApiException(429,"Chờ ít nhất 30 giây giữa các lần truy vấn giao dịch.");var result=await gateway.Query(attempt,ct);if(result is not null)await repository.Confirm(result,ct);}
 public async Task<string> Ipn(IQueryCollection query,CancellationToken ct){var result=gateway.Verify(query);if(result is null)return "97";return await repository.Confirm(result,ct);}
 public async Task<long?> Return(IQueryCollection query,CancellationToken ct){var result=gateway.Verify(query);if(result is null)return null;var attempt=await repository.Attempt(result.Reference,ct);return attempt?.Amount==result.Amount?attempt.BookingId:null;}
}
